const body = $input.first().json.body || {};
const recipients = Array.isArray(body.recipients) ? body.recipients : [];
const subject = body.subject || 'Official Notification from AOTMS';
const content = body.content || body.message || body.body || '';
const imageUrl = body.imageUrl || '';
const html = body.html || '';

// Generate clean responsive HTML with Cloudinary image banner
const finalHtml = html || `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 0; background-color: #f8fafc;">
  <div style="max-width: 600px; margin: 24px auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 4px 16px rgba(0,0,0,0.05);">
    ${imageUrl ? `<img src="${imageUrl}" alt="Banner" style="width: 100%; max-height: 340px; object-fit: cover; display: block; border-bottom: 1px solid #f1f5f9;" />` : ''}
    <div style="padding: 30px 26px;">
      <h2 style="font-size: 19px; font-weight: 700; color: #0f172a; margin: 0 0 16px 0;">${subject}</h2>
      <div style="font-size: 15px; line-height: 1.65; color: #334155; white-space: pre-wrap; word-break: break-word;">${content}</div>
    </div>
    <div style="padding: 16px 26px; background-color: #f8fafc; border-top: 1px solid #f1f5f9; text-align: center; font-size: 12px; color: #94a3b8;">
      Official Communication • AOTMS CRM
    </div>
  </div>
</body>
</html>
`.trim();

// Split into individual recipient items for Gmail node iteration
return recipients.map(email => {
  const cleanEmail = typeof email === 'string' ? email.trim() : (email.email || '');
  return {
    json: {
      email: cleanEmail,
      subject,
      content,
      imageUrl,
      html: finalHtml
    }
  };
});
